import {b,fmt,clamp,shells,heating,work,buoyancy,pendulum,falling} from '../math.js';
import {C,reflect,read,particles,molecule,atom,cell,neuron,plants,organelles} from '../scene-utils.js';
export default ({g,t,p,low})=>{let q=p[0],a=heating(q);particles(g,t,low?18:32,a.phase<1?0:a.phase<3?1:2,.7);let pts=[[0,-20],[.42,0],[3.76,0],[7.94,100],[30.54,100]];g.plot({title:b('Temperature vs heat: vertical scale −20 to 100°C','ताप बनाम ऊष्मा: ऊर्ध्व पैमाना −20 से 100°C'),xMax:31,yMin:-20,yMax:100,xLabel:'kJ',points:pts,marker:[q,a.temp]});return[read('Heat supplied','दी गई ऊष्मा',fmt(q),'kJ'),read('Temperature','तापमान',fmt(a.temp),'°C'),{label:b('Phase','अवस्था'),value:b(['Ice warming','Melting','Water warming','Boiling'][a.phase],['बर्फ का ताप बढ़ना','गलन','जल का ताप बढ़ना','क्वथन'][a.phase])}];};
